edits.new:
IF levelSensor >= 80 THEN
    valveARun := FALSE;
    valveBRun := FALSE;
    IF NOT processMode THEN
        mixMotorRun := TRUE;
        mixCompleteLatched := FALSE;
        state := MP_MIX_SIMPLE;
    ELSIF levelSensor >= 100 THEN
        valveCRun := FALSE;
        mixMotorRun := TRUE;
        mixCompleteLatched := FALSE;
        state := MP_MIX_C;
    ELSE
        valveCRun := TRUE;
        state := MP_FILL_C;
    END_IF;
ELSIF levelSensor >= 50 THEN
    valveARun := FALSE;
    valveBRun := TRUE;
    state := MP_FILL_B;
END_IF;
